      {COLOR_PICKER_ICON[name].map((d, i) => <path key={i} d={d} fill="currentColor" fillOpacity={active || name !== 'solid' || i !== 0 ? 1 : 0.35} fillRule="evenodd" clipRule="evenodd" />)}
