function useCloseOnOutside<T extends HTMLElement>(open: boolean, close: () => void) {
  const ref = useRef<T>(null)
  useEffect(() => {
    if (!open) return
    const onPointerDown = (event: PointerEvent) => {
      if (!(event.target instanceof Element)) return
      if (event.target.closest('[data-figma-floating-root="true"]')) return
      if (!ref.current?.contains(event.target)) close()
    }
    document.addEventListener('pointerdown', onPointerDown, true)
    return () => document.removeEventListener('pointerdown', onPointerDown, true)
  }, [open, close])
  return ref
}
// E3.3 — real DS tokens from the converter output (/api/dev/editor-tokens), fetched once and
// cached, feeding the ⬡ variable picker. The var name IS the token path (DEC-locked), so it
// doubles as the Figma-style label; the resolved value shows alongside for traceability.
type DsToken = { cssVar: string; value: string; dark?: string; group: string; kind: 'color' | 'dimension' | 'other'; path?: string; scopes?: string[]; original?: Record<string, string> }
// E6.13 — field → Figma's OWN scope model (the $scopes carried by the SSOT export; Dan: "we cannot
// have scopes for font showing dimensions"). Unmapped fields keep the kind filter only.
// 2.2 (Dan): token TIER from the cssVar prefix — the "library" a variable belongs to. Semantic +
// Component are shown by default (cover ~99% of real use); Primitive + Alias are toggled on via the
// picker's library dropdown when prototyping / hunting a fit.
type TokenTier = 'Primitive' | 'Alias' | 'Semantic' | 'Component'
const TOKEN_TIERS: TokenTier[] = ['Semantic', 'Component', 'Alias', 'Primitive']
const tierOf = (cssVar: string): TokenTier =>
  cssVar.startsWith('--sem-') ? 'Semantic'
  : cssVar.startsWith('--com') ? 'Component'
  : cssVar.startsWith('--al-') ? 'Alias'
  : 'Primitive'
const fieldScopes = (label: string): string[] | null =>
  /font family/i.test(label) ? ['FONT_FAMILY']
  : /font size|text size/i.test(label) ? ['FONT_SIZE']
  : /weight/i.test(label) && /font|text/i.test(label) ? ['FONT_WEIGHT']
  : /letter/i.test(label) ? ['LETTER_SPACING']
  : /line height/i.test(label) ? ['LINE_HEIGHT']
  : /gap|padding/i.test(label) ? ['GAP']
  : /radius|corner/i.test(label) ? ['CORNER_RADIUS']
  : /width|height/i.test(label) ? ['WIDTH_HEIGHT']
  : /opacity/i.test(label) ? ['OPACITY']
  : /stroke.*(weight|width)/i.test(label) ? ['STROKE_FLOAT']
  : /stroke|border/i.test(label) ? ['STROKE_COLOR', 'ALL_FILLS']
  // Dan 2026-07-08 (scope mismatch): TEXT_FILL-scoped colours were offered on BACKGROUND fills.
  // Text-colour fields get TEXT_FILL; background/shape fills do NOT (Figma's own scoping).
  : /text.*(fill|colou?r)|(fill|colou?r).*text/i.test(label) ? ['ALL_FILLS', 'TEXT_FILL']
  : /fill|background|paint/i.test(label) ? ['ALL_FILLS', 'FRAME_FILL', 'SHAPE_FILL']
  : /colou?r/i.test(label) ? ['ALL_FILLS', 'FRAME_FILL', 'SHAPE_FILL', 'TEXT_FILL']
  : null
let _dsTokenCache: DsToken[] | null = null
let _dsTokenRequest: Promise<DsToken[]> | null = null
function loadDsTokens(): Promise<DsToken[]> {
  if (_dsTokenCache) return Promise.resolve(_dsTokenCache)
  if (!_dsTokenRequest) {
    _dsTokenRequest = fetch('/api/dev/editor-tokens')
      .then((r) => (r.ok ? r.json() : { tokens: [] }))
      .then((d: { tokens: DsToken[] }) => {
        _dsTokenCache = d.tokens
        return d.tokens
      })
      .finally(() => { _dsTokenRequest = null })
  }
  return _dsTokenRequest
}
/* E4-G4 — real components available to insert (extracted-in-editor), for the Assets panel. */
type DsComponent = { name: string; importPath: string; category?: string; root?: 'project' | 'global'; file?: string; exports?: string[] }
function useDsComponents(active: boolean, nonce = 0): DsComponent[] {
  const [comps, setComps] = useState<DsComponent[]>([])
  useEffect(() => {
    if (!active) return
    fetch('/api/dev/editor-components').then((r) => (r.ok ? r.json() : { components: [] }))
      .then((d: { components: DsComponent[] }) => setComps(d.components)).catch(() => {})
  }, [active, nonce])
  return comps
}
function useDsTokens(): DsToken[] {
  const [toks, setToks] = useState<DsToken[]>(_dsTokenCache ?? [])
  useEffect(() => {
    if (_dsTokenCache) return
    loadDsTokens().then(setToks).catch(() => {})
  }, [])
  return toks
}
