  const scrub = useRef<{ startX: number; startVal: number; moved: boolean; pointerId: number; lastVal: number } | null>(null)
  const numeric = onChange && !bound && /^-?\d*\.?\d*$/.test(String(value).replace(/(px|%|°)$/, ''))
